from bs4 import BeautifulSoup
import requests

# Constants
URL = "http://example.com"


def task_func(url=URL, from_encoding="cp1251", use_lxml=False):
    """
    Fetch a web page, decode it with the specified encoding, and parse it with BeautifulSoup.

    Returns:
        BeautifulSoup: parsed HTML on success
        None: if the URL is empty/None, request fails, response status is not 200,
              decoding fails, or parsing fails
    """
    if not url:
        return None

    try:
        response = requests.get(url, timeout=10)
    except requests.RequestException:
        return None

    if response.status_code != 200:
        return None

    try:
        html = response.content.decode(from_encoding)
    except (LookupError, UnicodeDecodeError, AttributeError):
        return None

    parser = "lxml" if use_lxml else "html.parser"

    try:
        return BeautifulSoup(html, parser)
    except Exception:
        return None
